// Quicksand font for jsPDF Unicode support
export const quicksandNormal = "";
export const quicksandBold = "";

export function addQuicksandFonts(doc) {
  if (!doc) return;
  try {
    doc.addFileToVFS('Quicksand-normal.ttf', quicksandNormal);
    doc.addFont('Quicksand-normal.ttf', 'Quicksand', 'normal');
    doc.addFileToVFS('Quicksand-bold.ttf', quicksandBold);
    doc.addFont('Quicksand-bold.ttf', 'Quicksand', 'bold');
  } catch (err) {
    console.error('Failed to load Quicksand font into jsPDF:', err);
  }
}
